package com.healthcompanion.controller;
import com.healthcompanion.dto.DashboardSummary; import com.healthcompanion.repository.*; import com.healthcompanion.service.UserService; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/dashboard") public class DashboardController {private final UserService users;private final FoodScanRepository foods;private final ChatConversationRepository chats;private final WellnessEntryRepository wellness;public DashboardController(UserService u,FoodScanRepository f,ChatConversationRepository c,WellnessEntryRepository w){users=u;foods=f;chats=c;wellness=w;}@GetMapping("/summary") public DashboardSummary summary(Authentication a){var u=users.current(a.getName());var e=wellness.findTop30ByUserOrderByCreatedAtDesc(u);Double mood=e.isEmpty()?null:e.get(0).getMood().doubleValue();Double sleep=e.isEmpty()?null:e.stream().mapToDouble(x->x.getSleepHours()).average().orElse(0);return new DashboardSummary(u.getName(),foods.countByUser(u),chats.countByUser(u),wellness.countByUser(u),mood,sleep);}}
